import json
from datetime import datetime
from urllib.parse import urlsplit, parse_qs

MENU = [
    {"id": "1", "name": "蛋餅", "price": 30},
    {"id": "2", "name": "漢堡", "price": 45},
    {"id": "3", "name": "吐司", "price": 25},
    {"id": "4", "name": "奶茶", "price": 25},
    {"id": "5", "name": "豆漿", "price": 20},
    {"id": "6", "name": "鐵板麵", "price": 50},
    {"id": "7", "name": "蘿蔔糕", "price": 35},
    {"id": "8", "name": "紅茶", "price": 20},
]

VALID_STATUS = ("pending", "preparing", "done")
VALID_DINE = ("dine_in", "takeout")

ORDERS = []
_next_id = [1]


def _err(status, message):
    return status, {"error": message}


def _parse_body(body):
    if not body:
        return None, _err(400, "請提供 JSON 內容")
    try:
        if isinstance(body, (bytes, bytearray)):
            text = bytes(body).decode("utf-8")
        else:
            text = str(body)
        data = json.loads(text)
    except Exception:
        return None, _err(400, "JSON 格式錯誤")
    if not isinstance(data, dict):
        return None, _err(400, "請求內容必須是 JSON 物件")
    return data, None


def _menu_by_id(mid):
    for m in MENU:
        if m["id"] == mid:
            return m
    return None


def _copy_order(o):
    c = dict(o)
    c["items"] = [dict(i) for i in o["items"]]
    return c


def _get_menu():
    return 200, {"items": [dict(m) for m in MENU]}


def _create_order(body):
    data, err = _parse_body(body)
    if err:
        return err
    items = data.get("items")
    if not isinstance(items, list) or len(items) == 0:
        return _err(400, "請至少選擇一項餐點")
    dine_type = data.get("dine_type")
    if dine_type not in VALID_DINE:
        return _err(400, "用餐方式必須是內用或外帶")
    table_no = data.get("table_no", "")
    if table_no is None:
        table_no = ""
    if isinstance(table_no, bool) or not isinstance(table_no, (str, int)):
        return _err(400, "桌號格式錯誤")
    table_no = str(table_no).strip()
    if dine_type == "dine_in" and table_no == "":
        return _err(400, "內用必須填寫桌號")

    merged = {}
    order_ids = []
    for it in items:
        if not isinstance(it, dict):
            return _err(400, "餐點資料格式錯誤")
        mid = it.get("menu_item_id")
        if isinstance(mid, bool) or not isinstance(mid, (str, int)):
            return _err(400, "餐點編號格式錯誤")
        mid = str(mid)
        menu_item = _menu_by_id(mid)
        if menu_item is None:
            return _err(400, "找不到餐點編號：" + mid)
        qty = it.get("quantity")
        if isinstance(qty, bool) or not isinstance(qty, int):
            return _err(400, "數量必須是整數")
        if qty < 1:
            return _err(400, "數量必須至少為 1")
        if qty > 999:
            return _err(400, "數量過大")
        if mid in merged:
            merged[mid] += qty
        else:
            merged[mid] = qty
            order_ids.append(mid)

    lines = []
    total = 0
    for mid in order_ids:
        m = _menu_by_id(mid)
        qty = merged[mid]
        lines.append({
            "menu_item_id": mid,
            "name": m["name"],
            "price": m["price"],
            "quantity": qty,
        })
        total += m["price"] * qty

    order = {
        "id": str(_next_id[0]),
        "items": lines,
        "dine_type": dine_type,
        "table_no": table_no,
        "status": "pending",
        "total": total,
        "created_at": datetime.now().isoformat(timespec="seconds"),
    }
    _next_id[0] += 1
    ORDERS.append(order)
    return 201, _copy_order(order)


def _list_orders(query):
    status = None
    if "status" in query and query["status"]:
        status = query["status"][0]
    if status:
        if status not in VALID_STATUS:
            return _err(400, "狀態只能是 pending、preparing 或 done")
    result = [o for o in ORDERS if not status or o["status"] == status]
    result.sort(key=lambda o: (o["created_at"], int(o["id"])))
    return 200, {"items": [_copy_order(o) for o in result]}


def _update_order(order_id, body):
    order = None
    for o in ORDERS:
        if o["id"] == order_id:
            order = o
            break
    if order is None:
        return _err(404, "找不到這筆訂單")
    data, err = _parse_body(body)
    if err:
        return err
    status = data.get("status")
    if not isinstance(status, str) or status not in VALID_STATUS:
        return _err(400, "狀態只能是 pending、preparing 或 done")
    order["status"] = status
    return 200, _copy_order(order)


def _stats_today():
    today = datetime.now().date().isoformat()
    count = 0
    amount = 0
    qtys = {}
    for o in ORDERS:
        if o["created_at"][:10] != today:
            continue
        count += 1
        amount += o["total"]
        for l in o["items"]:
            qtys[l["menu_item_id"]] = qtys.get(l["menu_item_id"], 0) + l["quantity"]
    ranked = sorted(qtys.items(), key=lambda kv: (-kv[1], int(kv[0])))[:3]
    top = []
    for mid, q in ranked:
        m = _menu_by_id(mid)
        top.append({
            "menu_item_id": mid,
            "name": m["name"] if m else mid,
            "quantity": q,
        })
    return 200, {"order_count": count, "total_amount": amount, "top_items": top}


def handle(method, path, body):
    try:
        method = (method or "").upper()
        parts = urlsplit(path or "")
        p = parts.path
        query = parse_qs(parts.query)
        if not p.startswith("/"):
            p = "/" + p
        if len(p) > 1:
            p = p.rstrip("/")
        if p == "":
            p = "/"

        if p == "/menu":
            if method == "GET":
                return _get_menu()
            return _err(405, "不支援此請求方法")
        if p == "/orders":
            if method == "GET":
                return _list_orders(query)
            if method == "POST":
                return _create_order(body)
            return _err(405, "不支援此請求方法")
        if p.startswith("/orders/"):
            order_id = p[len("/orders/"):]
            if order_id and "/" not in order_id:
                if method == "PATCH":
                    return _update_order(order_id, body)
                return _err(405, "不支援此請求方法")
            return _err(404, "找不到此路徑")
        if p == "/stats/today":
            if method == "GET":
                return _stats_today()
            return _err(405, "不支援此請求方法")
        return _err(404, "找不到此路徑")
    except Exception:
        return _err(500, "伺服器發生錯誤")

