(function () {
  'use strict';

  var STATUS_LABEL = { pending: '待做', preparing: '製作中', done: '完成' };
  var STATUS_ORDER = ['pending', 'preparing', 'done'];
  var menu = [];
  var qty = {};
  var orders = [];
  var filter = 'all';
  var currentTab = 'order';
  var timer = null;

  function $(id) { return document.getElementById(id); }

  function api(method, path, body) {
    var opts = { method: method, headers: {} };
    if (body !== undefined) {
      opts.headers['Content-Type'] = 'application/json';
      opts.body = JSON.stringify(body);
    }
    return fetch('api/' + path, opts).then(function (res) {
      return res.text().then(function (text) {
        var data = null;
        try { data = text ? JSON.parse(text) : {}; } catch (e) { data = null; }
        if (!res.ok) {
          var msg = data && data.error ? String(data.error) : '伺服器錯誤（' + res.status + '）';
          throw new Error(msg);
        }
        if (data === null || typeof data !== 'object') {
          throw new Error('伺服器回應格式錯誤');
        }
        return data;
      });
    }, function () {
      throw new Error('無法連線到伺服器，請稍後再試');
    });
  }

  function showMessage(id, text, kind) {
    var el = $(id);
    el.textContent = text || '';
    el.className = 'message' + (text ? ' ' + (kind || 'info') : '');
  }

  function el(tag, cls, text) {
    var e = document.createElement(tag);
    if (cls) e.className = cls;
    if (text !== undefined) e.textContent = text;
    return e;
  }

  function formatTime(s) {
    if (!s) return '';
    return String(s).replace('T', ' ').slice(0, 16);
  }

  /* ---------- 分頁切換 ---------- */
  function switchTab(name) {
    currentTab = name;
    var btns = document.querySelectorAll('.tab-btn');
    for (var i = 0; i < btns.length; i++) {
      btns[i].classList.toggle('active', btns[i].getAttribute('data-tab') === name);
    }
    var names = ['order', 'kitchen', 'stats'];
    for (var j = 0; j < names.length; j++) {
      $('tab-' + names[j]).hidden = names[j] !== name;
    }
    if (timer) { clearInterval(timer); timer = null; }
    if (name === 'order') {
      loadMenu();
    } else if (name === 'kitchen') {
      loadOrders();
      timer = setInterval(function () { loadOrders(true); }, 10000);
    } else if (name === 'stats') {
      loadStats();
    }
  }

  /* ---------- 點餐 ---------- */
  function loadMenu() {
    api('GET', 'menu').then(function (data) {
      menu = Array.isArray(data.items) ? data.items : [];
      renderMenu();
    }).catch(function (err) {
      showMessage('order-message', '無法載入菜單：' + err.message, 'error');
    });
  }

  function renderMenu() {
    var list = $('menu-list');
    list.textContent = '';
    if (menu.length === 0) {
      list.appendChild(el('li', 'empty', '目前沒有可點的餐點'));
    }
    menu.forEach(function (m) {
      var id = String(m.id);
      var q = qty[id] || 0;
      var li = el('li', 'menu-item');
      var info = el('div', 'menu-info');
      info.appendChild(el('span', 'menu-name', m.name));
      info.appendChild(el('span', 'menu-price', '$' + m.price));
      li.appendChild(info);
      var ctl = el('div', 'qty-ctl');
      var minus = el('button', 'qty-btn', '−');
      minus.type = 'button';
      minus.setAttribute('data-id', id);
      minus.setAttribute('data-act', 'minus');
      minus.setAttribute('aria-label', '減少' + m.name);
      var num = el('span', 'qty-num', String(q));
      var plus = el('button', 'qty-btn', '+');
      plus.type = 'button';
      plus.setAttribute('data-id', id);
      plus.setAttribute('data-act', 'plus');
      plus.setAttribute('aria-label', '增加' + m.name);
      ctl.appendChild(minus);
      ctl.appendChild(num);
      ctl.appendChild(plus);
      li.appendChild(ctl);
      list.appendChild(li);
    });
    updateTotal();
  }

  function updateTotal() {
    var total = 0;
    menu.forEach(function (m) {
      total += (qty[String(m.id)] || 0) * Number(m.price);
    });
    $('order-total').textContent = '$' + total;
  }

  function currentDineType() {
    var radios = document.getElementsByName('dine_type');
    for (var i = 0; i < radios.length; i++) {
      if (radios[i].checked) return radios[i].value;
    }
    return 'dine_in';
  }

  function updateTableField() {
    var dineIn = currentDineType() === 'dine_in';
    $('table-label').classList.toggle('optional', !dineIn);
    $('table-no').placeholder = dineIn ? '例如 5（內用必填）' : '外帶可不填';
  }

  function submitOrder(ev) {
    ev.preventDefault();
    var items = [];
    menu.forEach(function (m) {
      var q = qty[String(m.id)] || 0;
      if (q > 0) items.push({ menu_item_id: String(m.id), quantity: q });
    });
    if (items.length === 0) {
      showMessage('order-message', '請至少選擇一項餐點（數量不可為 0）', 'error');
      return;
    }
    var dine = currentDineType();
    var table = $('table-no').value.trim();
    if (dine === 'dine_in' && table === '') {
      showMessage('order-message', '內用請填寫桌號', 'error');
      $('table-no').focus();
      return;
    }
    if (dine === 'takeout') table = '';
    var btn = $('submit-btn');
    btn.disabled = true;
    showMessage('order-message', '送出中…', 'info');
    api('POST', 'orders', { items: items, dine_type: dine, table_no: table }).then(function (order) {
      qty = {};
      $('table-no').value = '';
      renderMenu();
      showMessage('order-message', '訂單已送出！編號 ' + order.id + '，合計 $' + order.total, 'success');
    }).catch(function (err) {
      showMessage('order-message', '送出失敗：' + err.message, 'error');
    }).then(function () {
      btn.disabled = false;
    });
  }

  /* ---------- 廚房 ---------- */
  function loadOrders(silent) {
    api('GET', 'orders').then(function (data) {
      orders = Array.isArray(data.items) ? data.items : [];
      if (!silent) showMessage('kitchen-message', '');
      else showMessage('kitchen-message', '');
      renderOrders();
    }).catch(function (err) {
      showMessage('kitchen-message', '無法載入訂單：' + err.message, 'error');
    });
  }

  function renderOrders() {
    var box = $('orders-list');
    box.textContent = '';
    var shown = orders.filter(function (o) {
      return filter === 'all' || o.status === filter;
    });
    if (shown.length === 0) {
      box.appendChild(el('p', 'empty', '目前沒有訂單'));
      return;
    }
    shown.forEach(function (o) {
      var card = el('article', 'order-card status-' + o.status);
      var head = el('div', 'order-head');
      var where = o.dine_type === 'dine_in' ? '內用　桌號 ' + (o.table_no || '') : '外帶';
      head.appendChild(el('strong', 'order-id', '#' + o.id));
      head.appendChild(el('span', 'order-where', where));
      head.appendChild(el('span', 'badge badge-' + o.status, STATUS_LABEL[o.status] || o.status));
      card.appendChild(head);
      card.appendChild(el('div', 'order-time', formatTime(o.created_at)));
      var ul = el('ul', 'order-items');
      (o.items || []).forEach(function (it) {
        ul.appendChild(el('li', '', it.name + ' × ' + it.quantity));
      });
      card.appendChild(ul);
      card.appendChild(el('div', 'order-total', '合計 $' + o.total));
      var actions = el('div', 'order-actions');
      STATUS_ORDER.forEach(function (s) {
        var b = el('button', 'status-btn' + (o.status === s ? ' current' : ''), STATUS_LABEL[s]);
        b.type = 'button';
        b.setAttribute('data-id', String(o.id));
        b.setAttribute('data-status', s);
        if (o.status === s) b.disabled = true;
        actions.appendChild(b);
      });
      card.appendChild(actions);
      box.appendChild(card);
    });
  }

  function updateStatus(id, status) {
    api('PATCH', 'orders/' + encodeURIComponent(id), { status: status }).then(function (updated) {
      for (var i = 0; i < orders.length; i++) {
        if (String(orders[i].id) === String(id)) { orders[i] = updated; break; }
      }
      showMessage('kitchen-message', '');
      renderOrders();
    }).catch(function (err) {
      showMessage('kitchen-message', '更新狀態失敗：' + err.message, 'error');
    });
  }

  /* ---------- 營業額 ---------- */
  function loadStats() {
    api('GET', 'stats/today').then(function (data) {
      showMessage('stats-message', '');
      $('stat-count').textContent = String(data.order_count);
      $('stat-amount').textContent = '$' + data.total_amount;
      var ol = $('top-items');
      ol.textContent = '';
      var items = Array.isArray(data.top_items) ? data.top_items : [];
      if (items.length === 0) {
        ol.appendChild(el('li', 'empty', '今天還沒有銷售紀錄'));
      }
      items.forEach(function (t) {
        ol.appendChild(el('li', '', t.name + '　' + t.quantity + ' 份'));
      });
    }).catch(function (err) {
      showMessage('stats-message', '無法載入營業額：' + err.message, 'error');
    });
  }

  /* ---------- 事件綁定 ---------- */
  function init() {
    var tabBtns = document.querySelectorAll('.tab-btn');
    Array.prototype.forEach.call(tabBtns, function (b) {
      b.addEventListener('click', function () { switchTab(b.getAttribute('data-tab')); });
    });

    $('menu-list').addEventListener('click', function (ev) {
      var t = ev.target;
      if (!t || !t.getAttribute) return;
      var act = t.getAttribute('data-act');
      var id = t.getAttribute('data-id');
      if (!act || id === null) return;
      var q = qty[id] || 0;
      if (act === 'plus') q = Math.min(q + 1, 99);
      else q = Math.max(q - 1, 0);
      qty[id] = q;
      showMessage('order-message', '');
      renderMenu();
    });

    var radios = document.getElementsByName('dine_type');
    Array.prototype.forEach.call(radios, function (r) {
      r.addEventListener('change', updateTableField);
    });
    $('order-form').addEventListener('submit', submitOrder);

    $('refresh-orders').addEventListener('click', function () { loadOrders(); });
    $('refresh-stats').addEventListener('click', loadStats);

    var filterBtns = document.querySelectorAll('.filter-btn');
    Array.prototype.forEach.call(filterBtns, function (b) {
      b.addEventListener('click', function () {
        filter = b.getAttribute('data-filter');
        Array.prototype.forEach.call(filterBtns, function (x) {
          x.classList.toggle('active', x === b);
        });
        renderOrders();
      });
    });

    $('orders-list').addEventListener('click', function (ev) {
      var t = ev.target;
      if (!t || !t.getAttribute) return;
      var status = t.getAttribute('data-status');
      var id = t.getAttribute('data-id');
      if (status && id !== null) updateStatus(id, status);
    });

    updateTableField();
    switchTab('order');
  }

  init();
})();

