  top: 0;
  z-index: 10;
}
.topbar h1 { margin: 0 0 8px; font-size: 22px; }
.tabs { display: flex; gap: 6px; }
.tab-btn {
  flex: 1;
  padding: 12px 8px;
  font-size: 18px;
  border: none;
  border-radius: 10px 10px 0 0;
  background: #d9805c;
  color: #fff;
  cursor: pointer;
}
.tab-btn.active { background: #faf6ee; color: #c0562b; font-weight: bold; }
main { max-width: 900px; margin: 0 auto; padding: 16px; }
h2 { margin: 8px 0 12px; }
button {
  font-family: inherit;
  font-size: 17px;
  padding: 10px 16px;
  border-radius: 8px;
  border: 1px solid #bbb;
  background: #fff;
  cursor: pointer;
  min-height: 44px;
}
button:disabled { opacity: 0.6; cursor: default; }
button.primary {
  background: #c0562b;
  color: #fff;
  border-color: #c0562b;
  width: 100%;
  font-size: 20px;
  min-height: 52px;
}
