.message.info, .message.success, .message.error { padding: 10px 14px; }
.message.info { background: #e8f0fe; color: #1a3d7c; }
.message.success { background: #e3f5e1; color: #1b5e20; }
.message.error { background: #fdeaea; color: #a31515; }
.menu-list { list-style: none; padding: 0; margin: 0 0 16px; }
